(6284765, 929069, 86447, '<td valign="top">Your cat really steered you wrong!  LOL!</td>', 'Your cat really steered you wrong!  LOL!', '2011-01-16 15:59:31.000000', NULL, 1),
(6284767, 928140, 86447, '<td valign="top">a 9 from me.   Oddly fascinating... and so COOL!!</td>', 'a 9 from me.   Oddly fascinating... and so COOL!!', '2011-01-16 16:00:10.000000', NULL, 1),
(6284835, 928727, 61396, '<td valign="top">I like your engraving technique.</td>', 'I like your engraving technique.', '2011-01-16 17:25:55.000000', NULL, 1),
(6284837, 929240, 61396, '<td valign="top">I initially thought this to be a scull of some animal, so it was a relief to know that it isn''t, but that also uncovered the mystery, and I like mysteries.</td>', 'I initially thought this to be a scull of some animal, so it was a relief to know that it isn''t, but that also uncovered the mystery, and I like mysteries.', '2011-01-16 17:30:13.000000', NULL, 1),
(6284838, 928978, 61396, '<td valign="top">I like the way you tell a story.</td>', 'I like the way you tell a story.', '2011-01-16 17:31:29.000000', NULL, 1),
(6284841, 929269, 61396, '<td valign="top">It seems this rocky stuff is smiling at me.</td>', 'It seems this rocky stuff is smiling at me.', '2011-01-16 17:36:29.000000', NULL, 1),
(6284843, 929271, 61396, '<td valign="top">Extreme lighting and fisheye effect push the viewer out of balance.</td>', 'Extreme lighting and fisheye effect push the viewer out of balance.', '2011-01-16 17:40:35.000000', NULL, 1),
(6284844, 928140, 61396, '<td valign="top">I like that 4 legged creature, be it a dog or a chair.</td>', 'I like that 4 legged creature, be it a dog or a chair.', '2011-01-16 17:42:35.000000', NULL, 1),
(6284868, 929069, 65234, '<td valign="top">And red eyes and harsh light and an unusual crop.  Certainly not a soothingly balanced image, but I can''t quite figure out what effect it''s supposed to have so it''s tough to say if it''s effective or not.</td>', 'And red eyes and harsh light and an unusual crop.  Certainly not a soothingly balanced image, but I can''t quite figure out what effect it''s supposed to have so it''s tough to say if it''s effective or not.', '2011-01-16 18:29:08.000000', NULL, 1),
(6284884, 929046, 65234, '<td valign="top">Gotta'' love Bassetts :-)</td>', 'Gotta'' love Bassetts :-)', '2011-01-16 18:40:27.000000', NULL, 1),
(6284889, 928975, 65234, '<td valign="top">It''s going to take a LONG time for him to eat that apple!</td>', 'It''s going to take a LONG time for him to eat that apple!', '2011-01-16 18:44:32.000000', NULL, 1),
(6284891, 929297, 65234, '<td valign="top">The cat does not look like she wants to be participating in this ;-)</td>', 'The cat does not look like she wants to be participating in this ;-)', '2011-01-16 18:47:11.000000', NULL, 1),
(6284893, 928770, 65234, '<td valign="top">On a windy day, it looks like.</td>', 'On a windy day, it looks like.', '2011-01-16 18:49:17.000000', NULL, 1),
(6284896, 929208, 65234, '<td valign="top">The apparent difference in body size is pretty extreme.  Someone''s been hogging all the food!</td>', 'The apparent difference in body size is pretty extreme.  Someone''s been hogging all the food!', '2011-01-16 18:55:41.000000', NULL, 1),
(6284898, 929318, 65234, '<td valign="top">Nice motion blur, and it feel like he is about to smack right into the edge of the picture.</td>', 'Nice motion blur, and it feel like he is about to smack right into the edge of the picture.', '2011-01-16 18:59:10.000000', NULL, 1),
(6284899, 928705, 65234, '<td valign="top">Exceptionally disorienting!</td>', 'Exceptionally disorienting!', '2011-01-16 19:01:25.000000', NULL, 1),
(6284900, 929232, 65234, '<td valign="top">What an incredibly bizarre perspective and DOF!  I like it :-)</td>', 'What an incredibly bizarre perspective and DOF!  I like it :-)', '2011-01-16 19:01:31.000000', NULL, 1),
(6284901, 929076, 65234, '<td valign="top">Wonderfully bizarre image!  One I think I could study for a long time and come up with many different interpretations and still not be sure I "got" it.  Thank you for challenging me :-)</td>', 'Wonderfully bizarre image!  One I think I could study for a long time and come up with many different interpretations and still not be sure I "got" it.  Thank you for challenging me :-)', '2011-01-16 19:01:34.000000', NULL, 1),
(6284902, 929284, 65234, '<td valign="top">Very unusual composition; unsettling, but that appears to be the point.</td>', 'Very unusual composition; unsettling, but that appears to be the point.', '2011-01-16 19:01:39.000000', NULL, 1),
(6284903, 929210, 65234, '<td valign="top">Small person; big world.</td>', 'Small person; big world.', '2011-01-16 19:01:44.000000', NULL, 1),
(6284904, 928624, 65234, '<td valign="top">Really cool reflection!  Fun image.</td>', 'Really cool reflection!  Fun image.', '2011-01-16 19:01:51.000000', NULL, 1),
(6284905, 929231, 65234, '<td valign="top">Love those swirling clouds and the bright moon.</td>', 'Love those swirling clouds and the bright moon.', '2011-01-16 19:01:54.000000', NULL, 1),
(6284906, 929019, 65234, '<td valign="top">Rather Gothic in feel.</td>', 'Rather Gothic in feel.', '2011-01-16 19:01:57.000000', NULL, 1),
(6284907, 929052, 65234, '<td valign="top">Aw, poor little thing!  Doesn''t look too sure of its perch, either.</td>', 'Aw, poor little thing!  Doesn''t look too sure of its perch, either.', '2011-01-16 19:02:07.000000', NULL, 1),
(6284908, 929184, 65234, '<td valign="top">That is some colorful umbrella!  Interesting to have the child upright and yet the horizon is off-kilter.  Could be a hill, but visually a little disorienting (which is a good thing in this challenge).</td>', 'That is some colorful umbrella!  Interesting to have the child upright and yet the horizon is off-kilter.  Could be a hill, but visually a little disorienting (which is a good thing in this challenge).', '2011-01-16 19:02:17.000000', NULL, 1),
(6284909, 929300, 65234, '<td valign="top">Interesting, the leaf seems like it came from a completely different picture.</td>', 'Interesting, the leaf seems like it came from a completely different picture.', '2011-01-16 19:02:27.000000', NULL, 1),
(6284910, 929161, 65234, '<td valign="top">Definitely off-balance, interesting juxtaposition of objects.</td>', 'Definitely off-balance, interesting juxtaposition of objects.', '2011-01-16 19:02:33.000000', NULL, 1),
(6284911, 928727, 65234, '<td valign="top">Doesn''t feel terribly out of balance to me (there''s a nice diagonal to the composition) but very cool image.</td>', 'Doesn''t feel terribly out of balance to me (there''s a nice diagonal to the composition) but very cool image.', '2011-01-16 19:02:36.000000', NULL, 1),
